script:
(function () {
  'use strict';
  // Fixed-fractional position sizing (long or short).
  //   risk budget      = account x risk%
  //   risk per share   = |entry - stop|
  //   shares by risk   = floor((risk budget - round-trip costs) / risk per share)
  //   shares by cap    = floor(account x max position% / entry)
  //   shares           = min(shares by risk, shares by cap), never below 0
  //   loss at stop     = shares x risk per share + costs
  // Verified: $100,000 account, 1% risk, entry $50, stop $45, $5 costs, 15% cap -> 199 shares,
  // $9,950 position (9.95%), $1,000 loss at stop; target $60 -> 2.00 reward-to-risk, $1,985 net gain.
  // Cap binding: entry $50, stop $49.50, same account -> risk allows 1,990 shares, cap allows 300.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
  var SCENARIOS = [0.5, 1, 1.5, 2, 3];

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function pct(v) { return (isFinite(v) ? v : 0).toFixed(2) + '%'; }

  function size(account, riskPct, maxPct, entry, stop, costs) {
    var budget = account * riskPct / 100;
    var perShare = Math.abs(entry - stop);
    var byRisk = budget > costs ? Math.floor((budget - costs) / perShare + 1e-9) : 0;
    var byCap = Math.floor(account * maxPct / 100 / entry + 1e-9);
    var shares = Math.max(0, Math.min(byRisk, byCap));
    var value = shares * entry;
    var loss = shares > 0 ? shares * perShare + costs : 0;
    return {
      budget: budget, perShare: perShare, byRisk: byRisk, byCap: byCap, shares: shares,
      value: value, valuePct: value / account * 100, loss: loss, lossPct: loss / account * 100,
      stopPct: perShare / entry * 100, capped: byCap < byRisk
    };
  }

  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var account = num('psAccount'), riskPct = num('psRisk'), entry = num('psEntry'), stop = num('psStop'),
        maxPct = num('psMaxPos'), costs = num('psCosts'), target = num('psTarget');
    var side = document.getElementById('psSide').value;
    var error = document.getElementById('psError');
    var msg = '';
    if ([account, riskPct, entry, stop, maxPct, costs].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (account <= 0 || entry <= 0 || stop <= 0) msg = 'Account size, entry price and stop-loss must be greater than zero.';
    else if (riskPct <= 0 || riskPct > 100) msg = 'Risk per trade must be more than 0% and at most 100%.';
    else if (maxPct <= 0 || maxPct > 100) msg = 'Maximum position size must be more than 0% and at most 100%.';
    else if (costs < 0) msg = 'Trading costs cannot be negative.';
    else if (side === 'long' && stop >= entry) msg = 'For a long trade the stop-loss must be below the entry price.';
    else if (side === 'short' && stop <= entry) msg = 'For a short trade the stop-loss must be above the entry price.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var r = size(account, riskPct, maxPct, entry, stop, costs);
    set('psShares', whole.format(r.shares));
    set('psValue', money.format(r.value));
    set('psValuePct', pct(r.valuePct));
    set('psLoss', money.format(r.loss));
    set('psBudget', money.format(r.budget));
    set('psPerShare', money.format(r.perShare));
    set('psStopPct', pct(r.stopPct));
    set('psLossPct', pct(r.lossPct));
    var limit;
    if (r.shares === 0 && r.budget <= costs) limit = 'Trading costs use up the whole risk budget';
    else if (r.shares === 0) limit = 'Risk budget is smaller than the risk on one share';
    else if (r.capped) limit = 'Maximum position size (' + maxPct + '% of account)';
    else limit = 'Risk per trade (' + riskPct + '% of account)';
    set('psLimit', limit);

    var validTarget = !isNaN(target) && target > 0 &&
      ((side === 'long' && target > entry) || (side === 'short' && target < entry));
    if (validTarget) {
      var move = Math.abs(target - entry);
      set('psRatio', (move / r.perShare).toFixed(2) + ' : 1');
      set('psGain', money.format(Math.max(0, r.shares * move - (r.shares > 0 ? costs : 0))));
    } else {
      set('psRatio', '–');
      set('psGain', '–');
    }

    var body = document.getElementById('psTable');
    while (body.firstChild) body.removeChild(body.firstChild);
    SCENARIOS.forEach(function (p) {
      var s = size(account, p, maxPct, entry, stop, costs);
      var tr = document.createElement('tr');
      [p + '%' + (p === riskPct ? ' (yours)' : ''), whole.format(s.shares), money.format(s.value),
       pct(s.valuePct), money.format(s.loss)].forEach(function (t) {
        var td = document.createElement('td');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('psForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
